type ManualEntryExtension = {
  keywords?: string[];
  features?: string[];
  beginnerSteps?: string[];
  commonQuestions?: ManualQuestion[];
  tips?: string[];
  settingSections?: ManualSettingSection[];
};

const mergeUniqueText = (base: string[] = [], extra: string[] = []) => {
  const seen = new Set<string>();
  return [...base, ...extra].filter((item) => {
    const key = item.trim();
    if (!key || seen.has(key)) return false;
    seen.add(key);
    return true;
  });
};

const mergeQuestions = (
  base: ManualQuestion[] = [],
  extra: ManualQuestion[] = [],
): ManualQuestion[] | undefined => {
  const byTitle = new Map<string, ManualQuestion>();
  [...base, ...extra].forEach((question) => {
    if (question.title.trim()) byTitle.set(question.title, question);
  });
  const merged = [...byTitle.values()];
  return merged.length > 0 ? merged : undefined;
};

const mergeSettingSections = (
  base: ManualSettingSection[] = [],
  extra: ManualSettingSection[] = [],
): ManualSettingSection[] | undefined => {
  const sections = base.map(section => ({
    ...section,
    settings: [...section.settings],
  }));
  extra.forEach((section) => {
    const existing = sections.find(item => item.id === section.id);
    if (!existing) {
      sections.push({ ...section, settings: [...section.settings] });
      return;
    }
    existing.description = existing.description || section.description;
    const settingIds = new Set(existing.settings.map(setting => setting.id));
    section.settings.forEach((setting) => {
      if (!settingIds.has(setting.id)) {
        existing.settings.push(setting);
        settingIds.add(setting.id);
      }
    });
  });
  return sections.length > 0 ? sections : undefined;
};

