export const MANUAL_ENTRIES: ManualEntry[] = BASE_MANUAL_ENTRIES.map((entry) => {
  const extension = MANUAL_ENTRY_EXTENSIONS[entry.app];
  if (!extension) return entry;
  return {
    ...entry,
    keywords: mergeUniqueText(entry.keywords, extension.keywords),
    features: mergeUniqueText(entry.features, extension.features),
    beginnerSteps: mergeUniqueText(entry.beginnerSteps, extension.beginnerSteps),
    commonQuestions: mergeQuestions(entry.commonQuestions, extension.commonQuestions),
    tips: mergeUniqueText(entry.tips, extension.tips),
    settingSections: mergeSettingSections(entry.settingSections, extension.settingSections),
  };
});

